// Prepare one POST attempt. Caller contract:
//   msg.url      target URL            msg.payload  JSON body
//   msg.label    log label (optional)  msg.ackOnSuccess etc. pass through untouched
const st = msg._http || (msg._http = { attempt: 0 });
st.attempt += 1;
if (st.attempt === 1) {
    st.body  = msg.payload;
    st.label = msg.label || 'HTTP';
    st.max   = Math.max(1, Number(env.get('MAX_ATTEMPTS')) || 1);
    st.delay = Math.max(0, Number(env.get('RETRY_DELAY_MS')) || 1000);
}
delete msg.error;
delete msg.statusCode;
msg.payload        = st.body;
msg.method         = 'POST';
msg.headers        = { 'accept': 'text/plain', 'Content-Type': 'application/json' };
msg.requestTimeout = Number(env.get('TIMEOUT_MS')) || 10000;   // total request budget (connect + read)
node.status({ fill: 'blue', shape: 'dot', text: st.label + ' try ' + st.attempt + '/' + st.max });
return msg;

// Evaluate the attempt.  Output 1 = success, Output 2 = retry (-> delay), Output 3 = give up
const st    = msg._http || {};
const label = st.label || 'HTTP';
const code  = msg.statusCode;
const ok    = !msg.error && [200, 201, 202, 204].includes(code);
if (ok) {
    node.log('[' + label + '] HTTP ' + code + ' OK (attempt ' + st.attempt + '/' + st.max + ')');
    node.status({ fill: 'green', shape: 'dot', text: label + ' ' + code });
    msg.httpOk = true;
    delete msg._http;
    return [msg, null, null];
}
let reason;
if (msg.error) reason = (msg.error.message || String(msg.error));
else reason = 'HTTP ' + code + (typeof msg.payload === 'string' ? ' - ' + msg.payload.slice(0, 80) : '');
if (st.attempt < st.max) {
    node.warn('[' + label + '] attempt ' + st.attempt + '/' + st.max + ' FAILED (' + reason + ') - retry in ' + st.delay + ' ms');
    msg.delay = st.delay;
    return [null, msg, null];
}
node.warn('[' + label + '] FAILED after ' + st.attempt + ' attempt(s): ' + reason + '  url=' + msg.url);
node.status({ fill: 'red', shape: 'ring', text: label + ' failed' });
msg.httpOk    = false;
msg.httpError = reason;
msg.attempts  = st.attempt;
delete msg._http;
return [null, null, msg];

// Pydantic-equivalent validation of BatchPayload { badge_id, batch_id, containers[ {container_name, pallet_id, partA_type,
// partB_type, rack_id, final_product_name, tasks[ {operation_name, task_name, task_sequence} ]} ] }
const b = msg.payload;
const errs = [];
const isStr = v => typeof v === 'string';
const asInt = v => (typeof v === 'number' && Number.isInteger(v)) ? v
                 : (typeof v === 'string' && /^-?\d+$/.test(v.trim())) ? parseInt(v, 10) : null;
const clean = { badge_id: null, batch_id: null, containers: [] };
if (!b || typeof b !== 'object' || Array.isArray(b)) {
    errs.push('body: JSON object required');
} else {
    if (!isStr(b.badge_id)) errs.push('badge_id: string required'); else clean.badge_id = b.badge_id;
    if (!isStr(b.batch_id)) errs.push('batch_id: string required'); else clean.batch_id = b.batch_id;
    if (!Array.isArray(b.containers)) errs.push('containers: array required');
    else {
        const seen = new Set();
        b.containers.forEach((c, i) => {
            const cc = { tasks: [] };
            for (const f of ['container_name', 'pallet_id', 'partA_type', 'partB_type', 'rack_id', 'final_product_name']) {
                if (!c || !isStr(c[f])) errs.push('containers[' + i + '].' + f + ': string required'); else cc[f] = c[f];
            }
            if (cc.container_name !== undefined) {
                if (seen.has(cc.container_name)) errs.push('containers[' + i + '].container_name: duplicate within batch');
                seen.add(cc.container_name);
            }
            if (!c || !Array.isArray(c.tasks)) errs.push('containers[' + i + '].tasks: array required');
            else c.tasks.forEach((t, j) => {
                const seq = t ? asInt(t.task_sequence) : null;
                if (!t || !isStr(t.operation_name)) errs.push('containers[' + i + '].tasks[' + j + '].operation_name: string required');
                if (!t || !isStr(t.task_name))      errs.push('containers[' + i + '].tasks[' + j + '].task_name: string required');
                if (seq === null)                   errs.push('containers[' + i + '].tasks[' + j + '].task_sequence: integer required');
                else cc.tasks.push({ operation_name: t.operation_name, task_name: t.task_name, task_sequence: seq });
            });
            clean.containers.push(cc);
        });
    }
}
if (errs.length) { msg.statusCode = 422; msg.payload = { detail: errs }; return [msg, null]; }
node.log('[KITTING-API] batch received  badge=' + clean.badge_id + '  batch=' + clean.batch_id + '  containers=' + clean.containers.length);
msg.params = [JSON.stringify(clean)];
msg.badge_id = clean.badge_id;
return [null, msg];

const r = (Array.isArray(msg.payload) && msg.payload[0]) || {};
const pending = Number(r.pending_count) || 0;
node.log('[KITTING-API] stored  badge=' + r.badge_id + '  containers=' + r.containers_stored + '  tasks=' + r.tasks_stored + '  pending=' + pending);
msg.statusCode = 200;
msg.payload = { status: 'success', badge_id: r.badge_id, queue_status: 'pending', pending_count: pending };
return msg;

// Kitting bridge – evaluated every DB116 scan (1 s).  Outputs:
// 1 claim query | 2 mark 'sent' | 3 requeue badge | 4 Mendix kitting status | 5 PLC trigger write
const cur = msg.payload;
if (!cur || typeof cur !== 'object') return null;
const cfg = global.get('cfg');
if (!cfg) { node.warn('Configuration not loaded yet'); return null; }
const now = Date.now();
global.set('snap_DB116', { ts: now, v: cur });
const clean = s => String(s == null ? '' : s).replace(/\0/g, '').trim();
const K    = flow.get('kit') || { waiting: false, inFlight: 0, pending: null };
const prev = context.get('prev');
const bits = {};
const edge = k => { const c = cur[k] === true; bits[k] = c; return c && !(prev ? prev[k] === true : false); };
const eRelease = edge('release_new_data');
const eAck     = edge('data_received_ack');
const eStart   = edge('kitting_start_trigger');
const eDone    = edge('kitting_complete_trigger');
context.set('prev', bits);

const claim = [], markSent = [], requeue = [], mendix = [], plc = [];

// (1) PLC requests the next order, or an earlier request is still waiting for data
if (eRelease) node.log('[KITTING-PLC] release_new_data rising edge');
if ((eRelease || K.waiting) && !K.pending && (now - K.inFlight) > 15000) {
    K.inFlight = now;
    claim.push({ payload: '' });
}
// (2) PLC confirmed it has taken the data
if (eAck) { node.log('[KITTING-PLC] data_received_ack -> badge sent'); markSent.push({ payload: '' }); }
// (3) Kitting started / completed -> Mendix
const st = { MFGOrder: clean(cur.step4_batch_id), ContainerName: clean(cur.step4_container_id) };
if (eStart) mendix.push({ url: cfg.mendix.endpoints.kitting_status, label: 'Kitting-Started',
                          payload: Object.assign({}, st, { Started: true, Completed: bits.kitting_complete_trigger === true }) });
if (eDone)  mendix.push({ url: cfg.mendix.endpoints.kitting_status, label: 'Kitting-Completed',
                          payload: Object.assign({}, st, { Started: bits.kitting_start_trigger === true, Completed: true }) });
// (4) write-verify-trigger
if (K.pending) {
    const p = K.pending;
    const ok = Object.keys(p.data).every(k => cur[k] === p.data[k]);
    if (ok) {
        node.log('[KITTING-PLC] DB116 read-back verified for badge ' + p.badge + ' -> firing new_data_trigger');
        plc.push({ variable: 'new_data_trigger', payload: true });
        K.pending = null;
        node.status({ fill: 'green', shape: 'dot', text: 'delivered ' + p.badge });
    } else if (now - p.since > 10000) {
        node.warn('[KITTING-PLC] read-back mismatch for 10 s - badge ' + p.badge + ' returned to pending');
        requeue.push({ params: [p.badge] });
        K.pending = null; K.waiting = true;
    }
}
flow.set('kit', K);
return [claim, markSent, requeue, mendix, plc];

// Build the DB116 write set from the claimed badge.

const asciiTrunc = (v, n) => String(v == null ? '' : v).replace(/[^\x00-\x7F]/g, '?').slice(0, n);
const K = flow.get('kit') || { waiting: false, inFlight: 0, pending: null };
K.inFlight = 0;
const rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length) {
    if (!K.waiting) node.warn('[KITTING-PLC] No pending data - will keep checking every scan');
    K.waiting = true; flow.set('kit', K);
    node.status({ fill: 'yellow', shape: 'ring', text: 'waiting for data' });
    return null;
}
const r = rows[0];
const details = Array.isArray(r.details) ? r.details : [];
const seq = (opPrefix, task) => {
    const op = opPrefix.toUpperCase(), t = task.toLowerCase();
    for (const d of details) {
        if (String(d.operation_name || '').trim().toUpperCase().startsWith(op) &&
            String(d.task_name || '').trim().toLowerCase() === t) {
            return Math.max(-32768, Math.min(32767, Number(d.task_sequence) || 0));
        }
    }
    node.warn("[KITTING-PLC] TASK NOT FOUND op='" + opPrefix + "' task='" + task + "' available=" +
              JSON.stringify(details.map(d => [d.operation_name, d.task_name, d.task_sequence])));
    return 0;
};
const A = v => asciiTrunc(v, 40);
const data = {
    container_id: A(r.container_name), batch_id: A(r.batch_id),
    part_type_a: A(r.part_a_type), part_type_b: A(r.part_b_type),
    pallet_id: A(r.pallet_id), rack_id: A(r.rack_id),
    op10_operator: 'OP10_PartAssembly', op10_move_in: seq('OP10', 'movein'), op10_part_assembly: seq('OP10', 'part_assembly'),
    op10_bolt_torquing: seq('OP10', 'bolt_torquing'), op10_move_out: seq('OP10', 'moveout'),
    op20_operator: 'OP20_BearingAssembly', op20_move_in: seq('OP20', 'movein'), op20_bearing_press: seq('OP20', 'bearingpress'),
    op20_move_out: seq('OP20', 'moveout'),
    op30_operator: 'OP30_CameraInspection', op30_move_in: seq('OP30', 'movein'),
    op30_final_inspection: seq('OP30', 'final assembly inspection'), op30_move_out: seq('OP30', 'moveout')
};
K.waiting = false;
K.pending = { since: Date.now(), badge: r.badge_id, data };
flow.set('kit', K);
node.log('[KITTING-PLC] WRITE badge=' + r.badge_id + ' batch=' + r.batch_id + ' container=' + r.container_name +
         ' pallet=' + r.pallet_id + ' rack=' + r.rack_id + ' tasks=' + details.length + ' queue remaining=' + r.pending_after);
node.status({ fill: 'blue', shape: 'dot', text: 'written ' + r.badge_id + ' - verifying' });
const names = Object.keys(data);
return { variable: names, payload: names.map(k => data[k]), badge: r.badge_id };

const rows = Array.isArray(msg.payload) ? msg.payload : [];
node.log('[KITTING-PLC] queue update: ' + (rows.map(r => r.badge_id).join(', ') || 'no rows changed'));
return null;

// Central per-tab error handler.
//  * logs the error
//  * if the failing message belongs to an HTTP request (msg.res exists) -> answers HTTP 500 so the caller never hangs
//  * forwards a record to the failure registry (Configurations tab)
const err  = msg.error || {};
const src  = (err.source && (err.source.name || err.source.type)) || 'unknown';
const text = err.message || String(err);
node.warn('[' + src + '] ' + text);
const rec = { payload: { kind: 'error', ts: new Date().toISOString(), tab: 'WO', source: src, message: text } };
let resp = null;
if (msg.res) { msg.statusCode = 500; msg.payload = { detail: text }; resp = msg; }
return [resp, rec];

// DB57 rising-edge detector (replaces POLL A-D)
const cur = msg.payload;
if (!cur || typeof cur !== 'object') return null;
const cfg = global.get('cfg');
if (!cfg) { node.warn('Configuration not loaded yet'); return null; }
global.set('snap_DB57', { ts: Date.now(), v: cur });      // used by the REST routes (pallet-at-station-1 interlock)

// ignoreFirst = true : a bit that is already TRUE when the flow starts is NOT an event (start-up snapshot)
// ignoreFirst = false: it IS an event (Python POLL C / D start with last=None)
const RULES = {
    pallet_at_asrs_drop:          { out: 0, ignoreFirst: true  },
    pallet_at_station1:           { out: 1, ignoreFirst: true  },
    ready_to_receive_at_station1: { out: 2, ignoreFirst: false },
    ready_to_receive_at_asrs:     { out: 3, ignoreFirst: false }
};
const BUILD = [
    () => ({ url: cfg.amr.endpoints.asrs_drop,          payload: { status: true },                 label: 'AMR-POLL-A' }),
    () => ({ url: cfg.amr.endpoints.pallet_at_station1, payload: { status: true },                 label: 'AMR-POLL-B' }),
    () => ({ url: cfg.mendix.endpoints.confirmation,    payload: { DropPalletConfirmation: true }, label: 'AMR-POLL-C' }),
    () => ({ url: cfg.mendix.endpoints.confirmation,    payload: { DropPalletConfirmation: true }, label: 'AMR-POLL-D' })
];
const prev = context.get('prev');
const now  = {};
const outs = [null, null, null, null];
for (const k of Object.keys(RULES)) {
    const c = cur[k] === true;
    now[k] = c;
    const p = prev ? prev[k] === true : (RULES[k].ignoreFirst ? c : false);
    if (c && !p) { node.log('[' + k + '] rising edge'); outs[RULES[k].out] = BUILD[RULES[k].out](); }
}
context.set('prev', now);
return outs;

const cfg = global.get('cfg');
if (!cfg) { node.warn('Configuration not loaded yet (see Configurations tab)'); msg.statusCode = 503; msg.payload = { detail: "configuration not loaded" }; return [msg, null]; }
const b = msg.payload || {};
const asStr = v => (typeof v === 'string' || typeof v === 'number') ? String(v) : null;
const TaskId = asStr(b.TaskId), source = asStr(b.source), destination = asStr(b.destination);
const errs = [];
if (TaskId === null)      errs.push('TaskId: string required');
if (source === null)      errs.push('source: string required');
if (destination === null) errs.push('destination: string required');
if (errs.length) { msg.statusCode = 422; msg.payload = { detail: errs }; return [msg, null]; }
if (!source) { msg.statusCode = 200; msg.payload = { status: 'no Data' }; return [msg, null]; }

const tasks = global.get('amr_tasks') || {};
tasks[TaskId] = { source, destination, taskid: TaskId };
const keys = Object.keys(tasks), cap = (cfg.limits && cfg.limits.amrTasksMax) || 1000;
