global.set('amr_tasks', tasks);
node.log('[AMR-STEP-1] TaskId=' + TaskId + ' source=' + source + ' destination=' + destination);

msg.taskId  = TaskId;
msg.url     = cfg.amr.endpoints.get_task;
msg.payload = { taskId: TaskId, source, destination };
msg.label   = 'AMR-Task';
return [null, msg];

msg.statusCode = 200;
msg.payload = { status: 'task sent to AMR', taskId: msg.taskId };
return msg;

// Python FIX 3: tell Mendix the truth so it can retry on its side
msg.statusCode = 200;
msg.payload = { status: 'task delivery failed', taskId: msg.taskId, attempts: msg.attempts };
