const cfg = global.get('cfg');
if (!cfg) { node.warn('Configuration not loaded yet (see Configurations tab)'); msg.statusCode = 503; msg.payload = { error: "configuration not loaded" }; return [null, msg]; }
node.log('[AMR-UIERROR] fetching AMR errors');
msg.url = cfg.amr.errors_url;
msg.requestTimeout = 10000;      // Python FIX 4: never block forever
delete msg.payload;
return [msg, null];

if (typeof msg.payload === 'string') { msg.payload = { error: 'invalid JSON from AMR', status: 'AMR unreachable' }; }
msg.statusCode = 200;
