               payload: { TaskId, Order_Status: status }, label: 'AMR-Status' };
return [msg, post];

const FIELD = 'asrs_pick_position', VAR = 'AMR_asrs_pick_position', TAG = 'ASRS-PICK';
const toBool = v => {
    if (typeof v === 'boolean') return v;
    if (v === 1 || v === 0) return v === 1;
    if (typeof v === 'string') { const s = v.trim().toLowerCase(); if (s === 'true' || s === '1') return true; if (s === 'false' || s === '0') return false; }
    return null;
};
const val = toBool((msg.payload || {})[FIELD]);
