const cfg = global.get('cfg');
if (!cfg) { node.warn('Configuration not loaded yet (see Configurations tab)'); msg.statusCode = 503; msg.payload = { detail: "configuration not loaded" }; return [msg, null, null]; }
const toBool = v => {
    if (typeof v === 'boolean') return v;
    if (v === 1 || v === 0) return v === 1;
