const s = msg.status, src = s && s.source;
if (!src || src.type !== 's7 in') return null;
const key = src.name || src.id;
const plc = global.get('plc_status') || {};
const state = s.fill === 'green' ? 'online' : s.fill === 'yellow' ? 'connecting' : s.fill === 'red' ? 'offline' : 'unknown';
const was = plc[key] && plc[key].state;
plc[key] = { state, ts: new Date().toISOString() };
global.set('plc_status', plc);
if (was !== state) {
    const t = 'PLC link ' + key + ': ' + (was || 'n/a') + ' -> ' + state;
    if (state === 'online') node.log(t); else node.warn(t);
}
return null;

const reg = global.get('failures') || [];
const cfg = global.get('cfg') || {};
const max = (cfg.limits && cfg.limits.failuresMax) || 100;
const rec = (msg.payload && msg.payload.kind === 'error') ? msg.payload
          : { kind: 'delivery', ts: new Date().toISOString(), label: msg.label, url: msg.url, attempts: msg.attempts, message: msg.httpError };
reg.push(rec);
while (reg.length > max) reg.shift();
global.set('failures', reg);
return null;

const cfg = global.get('cfg') || {};
const plc = global.get('plc_status') || {};
const conn = {};
for (const k of Object.keys(plc)) conn[k] = plc[k].state === 'online';
msg.statusCode = 200;
msg.payload = {
    status: 'running',
    plc_ip: cfg.plc && cfg.plc.ip,
    plc_connections: conn,
    plc_detail: plc,
    mendix_endpoints: cfg.mendix && cfg.mendix.endpoints,
    amr_endpoints: cfg.amr && cfg.amr.endpoints,
    active_amr_tasks: Object.keys(global.get('amr_tasks') || {}).length,
    recent_failures: (global.get('failures') || []).slice(-10)
};
return msg;

// Reads {tagCount, namespaceIndex, lanes} from the inject node above.
// Builds NodeIds matching opcua_simulator_scalable.py's Generated/TagNNNNN
// pattern, splits them into `lanes` roughly-equal chunks, and sends one
// message per output — each output feeds its own OPC UA Client (Subscribe)
// node, i.e. its own independent Subscription (see guide Part on sharding).

const cfg = msg.payload || {};
const tagCount = cfg.tagCount || 100;
const ns = cfg.namespaceIndex || 2;
const lanes = cfg.lanes || 5;

const allNodeIds = [];
for (let i = 1; i <= tagCount; i++) {
    const padded = String(i).padStart(5, '0');
    allNodeIds.push('ns=' + ns + ';s=SimulatedPlant/Generated/Tag' + padded);
}

const perLane = Math.ceil(allNodeIds.length / lanes);
const outputs = [];
for (let l = 0; l < lanes; l++) {
    const chunk = allNodeIds.slice(l * perLane, (l + 1) * perLane);
    if (chunk.length === 0) { outputs.push(null); continue; }
    outputs.push({
        action: 'subscribe',
        topic: 'multiple',               
        payload: chunk.map(function (id) { return { nodeId: id }; }),
        lane: l,
        laneSize: chunk.length
    });
}

node.status({ fill: 'green', shape: 'dot', text: tagCount + ' tags across ' + lanes + ' lanes' });
return outputs;

// Every lane's OPC UA Client(Subscribe) output lands here.
// Reshape whatever this node-red-contrib-opcua version emits into one
// consistent shape the rest of the flow (throughput counter, TimescaleDB
// writer) can rely on regardless of which lane it came from.

const tagId = (msg.item && msg.item.nodeId) ? msg.item.nodeId : (msg.topic || 'unknown');
return {
    payload: {
        tag_id: tagId,
        value: msg.payload,
        quality: 1,
        time: new Date().toISOString()
    }
};

// Counts messages/second so you can SEE the pipeline actually handling
// 10, then 1000, then 50000 tags as you change tagCount above and redeploy.
// This is your sanity check before wiring in TimescaleDB.

let count = (context.get('count') || 0) + 1;
context.set('count', count);

if (!context.get('timerSet')) {
    context.set('timerSet', true);
    setInterval(function () {
        const c = context.get('count') || 0;
        context.set('count', 0);
        node.status({ fill: 'blue', shape: 'dot', text: c + ' msgs/sec' });
    }, 1000);
}

return msg;

// Accumulates normalized tag messages and flushes either every 2s or
// every 500 rows, whichever comes first — see the TimescaleDB section of
// the guide for why this matters instead of one INSERT per tag change.
// This node's output is a PLACEHOLDER wire point: connect it to your own
// Postgres/Timescale node once configured (see guide).

let buffer = context.get('buffer') || [];
buffer.push(msg.payload);
context.set('buffer', buffer);

const MAX_BATCH_SIZE = 500;

if (!context.get('flushTimerSet')) {
    context.set('flushTimerSet', true);
    setInterval(function () {
        const pending = context.get('buffer') || [];
        if (pending.length > 0) {
            context.set('buffer', []);
            node.send({ payload: pending });
        }
    }, 2000);
}

if (buffer.length >= MAX_BATCH_SIZE) {
    context.set('buffer', []);
    return { payload: buffer };
}
return null;

// See guide, Part: Email Alerts. Compares time since the last message
// this flow processed against a threshold, and only emits (triggering
// an email) when something looks wrong -- not on every healthy tick.

const last = flow.get('lastMessageTime');
const ageMs = last ? (Date.now() - last) : Infinity;
const THRESHOLD_MS = 5 * 60 * 1000; // 5 minutes

if (ageMs > THRESHOLD_MS) {
    return {
        payload: {
            subject: 'ALERT: OPC UA ingestion stalled',
            text: 'No messages processed in the last ' + Math.round(ageMs / 1000) + ' seconds. Check the simulator, endpoint, and Node-RED logs.\nJAI SHRI RAM!'
        }
    };
}
return null;

// Feeds the health check above. Wire this as a SECOND wire off
// 'Throughput Counter' (Node-RED lets one output fan out to multiple
// nodes) if you want the health check to reflect true pipeline activity.
flow.set('lastMessageTime', Date.now());
return null;

// Takes the whole batch array from Batch Buffer and constructs ONE
// multi-row INSERT instead of hundreds of individual ones.

const rows = msg.payload; // array of {tag_id, value, quality, time}

const values = [];
const placeholders = rows.map(function (r, i) {
    const base = i * 4;
    values.push(r.time, r.tag_id, r.value, r.quality);
    return `($${base + 1}, $${base + 2}, $${base + 3}, $${base + 4})`;
}).join(', ');

msg.query = `
    INSERT INTO tag_data (time, tag_id, value, quality)
    VALUES ${placeholders}
    ON CONFLICT (time, tag_id) DO NOTHING;
`;
msg.params = values; // most Postgres nodes read parameterized values from msg.params

return msg;

