function readInt16BE(bytes, index) {
    let val = (bytes[index] << 8) | bytes[index + 1];
    if (val & 0x8000) val -= 0x10000;
    return val;
}

function DecodeQM30(bytes) {

    // Header bytes (skip)
    // 01 = Slave ID
    // 03 = Function code
    // 03 = Dummy byte count
    const START = 3;

    // Device inserts +1 byte after 6 registers
    const SHIFT_AT = 6;       // after register 40006
    const EXTRA_BYTE = 1;

    let d = {};

    // Register reader with automatic shift correction
    function reg(n, scale) {
        let idx;

        if (n <= SHIFT_AT) {
            idx = START + (n - 1) * 2;
        } else {
            idx = START + (n - 1) * 2 + EXTRA_BYTE;
        }

        return readInt16BE(bytes, idx) / scale;
    }

    // ---------------------- REGISTERS ----------------------

    d.x_rms_velocity_insec        = reg(1, 10000);
    d.x_hf_rms_acc_g              = reg(2, 1000);
    d.y_rms_velocity_insec        = reg(3, 10000);
    d.y_hf_rms_acc_g              = reg(4, 1000);
    d.z_rms_velocity_insec        = reg(5, 10000);
    d.z_hf_rms_acc_g              = reg(6, 1000);

    // Temperature (Fahrenheit)
    let tempF = reg(7, 100);
    d.temperature_f = tempF;

    // Temperature in Celsius
    // d.temperature_c = (tempF - 32) * 5 / 9;

    d.x_fullband_pkpk_acc_g       = reg(8, 1000);
    d.y_fullband_pkpk_acc_g       = reg(9, 1000);
    d.z_fullband_pkpk_acc_g       = reg(10,1000);

    d.x_hf_pk_acc_g               = reg(11,1000);
    d.y_hf_pk_acc_g               = reg(12,1000);
    d.z_hf_pk_acc_g               = reg(13,1000);

    d.x_hf_crest_factor           = reg(14,1000);
    d.y_hf_crest_factor           = reg(15,1000);
    d.z_hf_crest_factor           = reg(16,1000);

    d.x_hf_kurtosis               = reg(17,1000);
    d.y_hf_kurtosis               = reg(18,1000);
    d.z_hf_kurtosis               = reg(19,1000);

    d.x_fullband_crest_factor     = reg(20,1000);
    d.y_fullband_crest_factor     = reg(21,1000);
    d.z_fullband_crest_factor     = reg(22,1000);

    d.x_fullband_kurtosis         = reg(23,1000);
    d.y_fullband_kurtosis         = reg(24,1000);
    d.z_fullband_kurtosis         = reg(25,1000);

    d.x_peak_velocity_freq_hz     = reg(26,10);
    d.y_peak_velocity_freq_hz     = reg(27,10);
    d.z_peak_velocity_freq_hz     = reg(28,10);

    d.motor_run_flag              = reg(29,1);

    d.x_fullband_peak_acc_freq_hz = reg(30,10);
    d.y_fullband_peak_acc_freq_hz = reg(31,10);
    d.z_fullband_peak_acc_freq_hz = reg(32,10);

    d.xyz_hf_rms_acc_g            = reg(33,1000);

    d.x_fullband_rms_acc_g        = reg(34,1000);
    d.y_fullband_rms_acc_g        = reg(35,1000);
    d.z_fullband_rms_acc_g        = reg(36,1000);

    d.x_rms_velocity_mm_sec       = reg(37,1000);
    d.x_hf_rms_acc_g2             = reg(38,1000);

    d.y_rms_velocity_mm_sec       = reg(39,1000);
    d.y_hf_rms_acc_g2             = reg(40,1000);

    d.z_rms_velocity_mm_sec       = reg(41,1000);
    d.z_hf_rms_acc_g2             = reg(42,1000);

    d.temperature_c2             = reg(43,100); // this register may not be actual temperature

    return d;
}

