  String(nextBadge.batch_id || ""),
  String(c.part_a_type || c.partA_type || ""),
  String(c.part_b_type || c.partB_type || ""),
  String(c.pallet_id || ""),
  String(c.rack_id || ""),
  "OP10_PartAssembly",
  getSeq("OP10", "movein"),
  getSeq("OP10", "part_assembly"),
