const plcBatch = flow.get("step4_batch_id");
const plcContainer = flow.get("step4_container_id");

const queue = global.get("WO_QUEUE") || [];
const active = queue.find(b => b.queue_status === "processing" || b.queue_status === "sent");

const batchId = (plcBatch && plcBatch.length > 0) ? plcBatch : (active ? active.batch_id : "UNKNOWN_BATCH");
const containerId = (plcContainer && plcContainer.length > 0) ? plcContainer : (active && active.containers && active.containers[0] ? active.containers[0].container_name : "UNKNOWN_CONTAINER");

const endpoints = global.get("MENDIX_ENDPOINTS") || {};
msg.url = endpoints.kitting_status;
