/*
 * NODE PURPOSE: Selects the next container and prepares the 19 PLC DB116 values.
 * INPUT: PLC release DB116.DBX0.0 OR an internal link kick.
 * COMMANDS:
 *   global.get("WO_QUEUE") -> reads the FIFO work-order queue.
 *   queue.find(...)        -> prevents a second container being loaded while one is active.
 *   flow.set("waiting",true) -> remembers that PLC requested data while another container runs.
 *   queue.find(pending)    -> selects the oldest pending work order.
 *   Number.isInteger(...)  -> safely chooses the next container index.
 *   tasks.find(...)        -> finds a task sequence by operation/task name.
 *   Number(...)            -> converts a task sequence to a numeric PLC value.
 *   vars[]                 -> ordered names of the 19 S7 variables.
 *   vals[]                 -> values in exactly the same order as vars[].
 *   flow.set("pending_write",...) -> stores expected values and retry timing for verification.
 *   return msg             -> sends the multi-variable write request to the S7 Out node.
 *
 * IMPORTANT:
 *   This node does NOT set DB116.DBX514.0. The verification node triggers the PLC
 *   only after the read-back matches all expected values.
 */

// FUNCTION: Fetch Next Badge -> DB116 Data
// PURPOSE: Select the oldest pending badge and write ONE container to PLC DB116.
// INPUT  : PLC release DB116.DBX0.0, or an internal "kick" message.
// OUTPUT : Output 1 = the 19 data values for the S7 write.
//          The NewData trigger is NOT sent here: "Verify Write -> Trigger" raises it
//          only after the PLC read-back confirms that all 19 values are in DB116.
// LOCK   : The active badge is derived from the queue (status processing/sent),
//          so there is no separate lock that could be lost on restart.

// 1. Load the shared FIFO queue and look for an active badge.
let queue = global.get("WO_QUEUE") || [];
const active = queue.find(b => ["processing", "sent"].includes(b.queue_status));
if (active) {
    // Remember the release; Check Mendix Response re-triggers this node after completion.
    flow.set("waiting", true);
    node.status({fill:"yellow", shape:"ring", text:`waiting for ACK/complete: ${active.badge_id}`});
    return null;
}

// 2. Select the oldest pending badge; wait if the queue is empty.
const badge = queue.find(b => b.queue_status === "pending");
if (!badge) {
    flow.set("waiting", true);
    node.status({fill:"yellow", shape:"ring", text:"PLC waiting – queue empty"});
    return null;
}

// 3. Get the next container and verify it exists with a task array.
const index = Number.isInteger(badge.next_container_index) ? badge.next_container_index : 0;
if (!Array.isArray(badge.containers) || index >= badge.containers.length) {
    badge.queue_status = "completed";
    global.set("WO_QUEUE", queue);
    node.warn(`Badge ${badge.badge_id} has no remaining containers; marked completed.`);
    return null;
}
const c = badge.containers[index];
if (!c || !Array.isArray(c.tasks)) {
    badge.queue_status = "write_failed";
    global.set("WO_QUEUE", queue);
    node.error(`Badge ${badge.badge_id}, container index ${index} has invalid tasks; marked write_failed.`);
    return null;
}

// 4. Reserve the badge/container (this is the lock).
badge.queue_status = "processing";
badge.current_container_index = index;
global.set("WO_QUEUE", queue);
flow.set("waiting", false);

// 5. Find the requested task sequence; missing or invalid values become zero.
const tasks = c.tasks;
function seq(op, task) {
    const t = tasks.find(x => String(x.operation_name || "").trim().toUpperCase().startsWith(op) && String(x.task_name || "").trim().toLowerCase() === task);
    if (!t) { node.warn(`TASK NOT FOUND op=${op} task=${task}; writing 0`); return 0; }
    const n = Number(t.task_sequence);
    return Number.isFinite(n) ? n : 0;
}

// 6. S7 variable names: keep this order aligned exactly with the values below.
const vars = ["DB116_container_id","DB116_batch_id","DB116_part_type_a","DB116_part_type_b","DB116_pallet_id","DB116_rack_id","DB116_op10_operator","DB116_op10_move_in","DB116_op10_part_assembly","DB116_op10_bolt_torquing","DB116_op10_move_out","DB116_op20_operator","DB116_op20_move_in","DB116_op20_bearing_press","DB116_op20_move_out","DB116_op30_operator","DB116_op30_move_in","DB116_op30_final_inspection","DB116_op30_move_out"];

// 7. Prepare 19 PLC values in the same order as vars (do not reorder).
const vals = [String(c.container_name || ""),String(badge.batch_id || ""),String(c.partA_type || c.part_a_type || ""),String(c.partB_type || c.part_b_type || ""),String(c.pallet_id || ""),String(c.rack_id || ""),"OP10_PartAssembly",seq("OP10","movein"),seq("OP10","part_assembly"),seq("OP10","bolt_torquing"),seq("OP10","moveout"),"OP20_BearingAssembly",seq("OP20","movein"),seq("OP20","bearingpress"),seq("OP20","moveout"),"OP30_CameraInspection",seq("OP30","movein"),seq("OP30","final assembly inspection"),seq("OP30","moveout")];

// 8. Start the write-confirmation record used by "Verify Write -> Trigger".
const cfg = flow.get("cfg") || {};
flow.set("pending_write", {
    badge_id: badge.badge_id,
    container_index: index,
    vars: vars,
    vals: vals,
    attempts: 1,
    started: Date.now(),
    timeout_ms: cfg.write_confirm_timeout_ms || 3000,
    max_attempts: cfg.write_max_attempts || 3
});

node.status({fill:"blue", shape:"dot", text:`writing ${badge.badge_id} / ${c.container_name}`});

// 9. Build the S7 data-write message containing all 19 values.
return {topic:"kitting_data", variable:vars, payload:vals, badge_id:badge.badge_id, container_index:index};

/*
 * NODE PURPOSE: Confirms the 19 DB116 values were written before notifying the PLC.
 * INPUT: msg.payload is expected to be an object keyed by S7 variable name.
 * COMMANDS:
 *   flow.get("pending_write") -> gets the expected write record.
 *   same(name,expected)       -> compares one PLC read-back value with its target.
 *   filter(...)               -> builds a list of variables that do not match.
 *   Date.now()                -> checks whether the verification timeout expired.
 *   flow.set(...)             -> clears or updates the pending-write record.
 *   return [trigger,retry]    -> output 1 triggers NewData; output 2 retries S7 write.
 *   global.get/set            -> updates the queue to write_failed after final failure.
 *
 * SAFETY:
 *   If any value remains mismatched after all retries, the PLC trigger is NOT sent.
 *   Read-back equality alone can match stale data; a PLC sequence/ack handshake is
 *   recommended for production-grade confirmation.
 */

// FUNCTION: Verify Write -> Trigger
// PURPOSE: Raise DB116.DBX514.0 (NewData Trigger) ONLY after the PLC read-back
//          shows that all 19 values written by "Fetch Next Badge" are in DB116.
// INPUT  : msg.payload = object {variable_name: value} from the all-variables S7 read (every cycle).
// OUTPUT : Output 1 = NewData trigger (TRUE) | Output 2 = retry of the data write.
// FAIL-SAFE: If the values never appear (write failed, array format unsupported,
//            PLC unreachable) the write is retried; after max attempts the badge is
//            set to 'write_failed', an error is raised and the trigger is NEVER sent.

// 1. Nothing to verify unless a write is pending.
const pw = flow.get("pending_write");
if (!pw) return null;
const data = msg.payload;
if (!data || typeof data !== "object") return null;

// 2. Compare every written register with the value read back from the PLC.
//    Strings are compared trimmed and limited to the 40 characters defined in the S7 address.
function same(name, expected) {
    const got = data[name];
    if (typeof expected === "number") return Number(got) === expected;
    return String(got == null ? "" : got).trim() === String(expected).slice(0, 40).trim();
}
const bad = pw.vars.filter((name, i) => !same(name, pw.vals[i]));

// 3. All values confirmed -> release the trigger.
if (bad.length === 0) {
    flow.set("pending_write", null);
    node.status({fill:"green", shape:"dot", text:`write verified ${pw.badge_id} -> trigger`});
    return [{topic:"kitting_trigger", variable:"DB116_new_data_trigger", payload:true,
             badge_id: pw.badge_id, container_index: pw.container_index}, null];
}

// 4. Still inside the confirmation window -> keep waiting.
if (Date.now() - pw.started < pw.timeout_ms) {
    node.status({fill:"yellow", shape:"ring", text:`verifying ${pw.vars.length - bad.length}/${pw.vars.length}`});
    return null;
}

// 5. Timeout: retry the write while attempts remain.
if (pw.attempts < pw.max_attempts) {
    pw.attempts += 1;
    pw.started = Date.now();
    flow.set("pending_write", pw);
    node.warn(`DB116 write not confirmed (${bad.join(", ")}); retry ${pw.attempts}/${pw.max_attempts}`);
    node.status({fill:"red", shape:"ring", text:`retry write ${pw.attempts}/${pw.max_attempts}`});
    return [null, {topic:"kitting_data_retry", variable: pw.vars, payload: pw.vals,
                   badge_id: pw.badge_id, container_index: pw.container_index}];
}

// 6. Give up: never trigger the PLC with unconfirmed data.
const queue = global.get("WO_QUEUE") || [];
const badge = queue.find(x => x.badge_id === pw.badge_id);
if (badge) {
    badge.queue_status = "write_failed";      // releases the lock; resubmit the work order to try again
    badge.current_container_index = null;
    global.set("WO_QUEUE", queue);
}
flow.set("pending_write", null);
flow.set("waiting", true);                    // a re-submitted work order is served immediately
node.status({fill:"red", shape:"dot", text:`write_failed ${pw.badge_id}`});
node.error(`DB116 write NOT confirmed after ${pw.max_attempts} attempts for badge ${pw.badge_id}. Trigger not sent. Mismatch: ${bad.join(", ")}`);
return null;

/*
 * NODE PURPOSE: Handles PLC Data Received ACK at DB116.DBX0.1.
 * INPUT: Only TRUE reaches this node because the preceding Switch filters FALSE.
 * COMMANDS:
 *   flow.get("pending_write") -> ensures data verification is already complete.
 *   global.get("WO_QUEUE")    -> reads the shared queue.
 *   queue.find(processing)    -> finds the badge currently reserved for PLC transfer.
 *   badge.queue_status="sent" -> records that PLC acknowledged receiving the data.
 *   new Date().toISOString() -> stores the acknowledgement timestamp.
 *   global.set(...)           -> saves the updated queue record.
 *   msg.payload               -> prepares an acknowledgement information object.
 *   return msg                -> forwards the acknowledgement to its output.
 *
 * IMPORTANT:
 *   "sent" means data received by PLC; it does NOT mean the kitting operation finished.
 */

/* PURPOSE: Process the PLC data-received acknowledgement (DB116.DBX0.1).
 * INPUT : msg.topic = DB116_data_received_ack. Only TRUE values arrive here
 *         (the Rising Edge switch removes FALSE).
 * STATE : processing -> sent. "sent" means the PLC acknowledged receipt, not that
 *         the container is finished.
 * SAFETY: The status change itself makes the ACK idempotent: a repeated ACK finds
 *         no 'processing' badge and is ignored. An ACK that arrives while the
 *         write is still unverified is also ignored.
 */

// Ignore an ACK that arrives before the data write was confirmed.
if (flow.get("pending_write")) {
    node.warn("PLC ACK received while DB116 write is still unverified. ACK ignored.");
    node.status({fill:"yellow", shape:"ring", text:"ACK before write verified"});
    return null;
}

// Find the one queue record reserved by Fetch Next Badge.
const queue = global.get("WO_QUEUE") || [];
const badge = queue.find(item => item.queue_status === "processing");
if (!badge) {
    node.warn("PLC ACK received, but no processing badge was found. ACK ignored.");
    node.status({fill:"yellow", shape:"ring", text:"ACK without processing badge"});
    return null;
}

// Store acknowledgement details for traceability.
badge.queue_status = "sent";
badge.plc_ack_received = true;
badge.plc_ack_at = new Date().toISOString();
badge.acknowledged_container_index = badge.current_container_index;
global.set("WO_QUEUE", queue);

node.status({fill:"green", shape:"dot", text:`PLC ACK OK: ${badge.badge_id}`});
msg.payload = {
    acknowledgement: "PLC_DATA_RECEIVED_ACK",
    result: "accepted",
    badge_id: badge.badge_id,
    container_index: badge.current_container_index,
    queue_status: badge.queue_status,
    acknowledged_at: badge.plc_ack_at,
    plc_tag: "DB116.DBX0.1"
};
return msg;

/*
 * NODE PURPOSE: Builds the Mendix REST body when PLC reports Kitting Started.
 * INPUT: msg.topic from DB116 kitting-start or completion trigger.
 * COMMANDS:
 *   flow.get("cfg")       -> reads the configured Mendix endpoint.
 *   flow.get("step4")     -> reads cached PLC batch/container identifiers.
 *   global.get("WO_QUEUE")-> finds the active work order and current container.
 *   msg.topic comparison -> identifies Started versus Completed event.
 *   msg.url/method       -> configures the HTTP Request node.
 *   msg.headers          -> sets JSON request headers.
 *   msg.payload           -> builds MFGOrder, ContainerName, Started and Completed.
 *   return msg            -> sends the request to the Mendix HTTP Request node.
 *
 * EVENT CONTRACT:
 *   Started event:   Started=true, Completed=false.
 *   Completed event: Started=false, Completed=true.
 */

// FUNCTION: Build Mendix Kitting STARTED Payload
// EVENT CONTRACT: STARTED = Started:true/Completed:false; COMPLETED = Started:false/Completed:true.
// PURPOSE: Convert PLC Started/Completed triggers into Mendix REST JSON.
// INPUT: msg.topic identifies the PLC start or completion trigger.
// OUTPUT: HTTP POST request containing MFGOrder, ContainerName, Started, Completed.
// ACK: DB116.DBX0.1 confirms data receipt; DB116.DBX0.3 indicates process completion.
// 1. Load Mendix configuration and cached PLC Step-4 identifiers.
const cfg = flow.get("cfg") || {};
const ids = flow.get("step4") || {};
// 2. Identify the event from the PLC input topic.
//    START input -> Started=true, Completed=false.
//    COMPLETE input -> Started=false, Completed=true.
const isStart = msg.topic === "DB116_kitting_start_trigger";
// 3. Load the queue and identify the currently active badge.
const queue = global.get("WO_QUEUE") || [];
const active = queue.find(b => ["processing", "sent"].includes(b.queue_status));
const badgeId = active ? active.badge_id : null;
// 4. Read the active container index and retrieve its container data.
const index = active ? active.current_container_index : null;
const activeContainer = active && Array.isArray(active.containers) ? active.containers[index] : null;
// 5. Get batch and container IDs from PLC cache or active queue data.
const batchId = ids.batch || (active ? active.batch_id : "UNKNOWN_BATCH");
const containerId = ids.container || (activeContainer ? activeContainer.container_name : "UNKNOWN_CONTAINER");
// 5b. Warn if the container reported by the PLC differs from the queue's active container.
if (ids.container && activeContainer && ids.container !== activeContainer.container_name) {
    node.warn(`PLC container ${ids.container} differs from queue container ${activeContainer.container_name}; check PLC/queue state.`);
}
// 6. Stop processing if the Mendix REST endpoint is not configured.
if (!cfg.mendix_kitting_url) {
    node.error("Mendix kitting URL is not configured.");
    return null; // No HTTP request is generated.
}
// 7. Store event metadata for the response-handling Function node.
msg.kit_event = isStart ? "started" : "completed";
msg.kit_badge = badgeId;
msg.kit_container_index = index;
msg.kit_batch = batchId;
msg.kit_container = containerId;
// 8. Configure the Mendix REST API request as an HTTP POST.
msg.url = cfg.mendix_kitting_url;
msg.method = "POST";
msg.headers = { "accept": "text/plain", "Content-Type": "application/json" };
// 9. Build the JSON body expected by the configured Mendix endpoint.
msg.payload = {
    MFGOrder: batchId, // Manufacturing order or batch identifier.
    ContainerName: containerId, // Currently active container.
    Started: isStart, // TRUE only for the Kitting Started event.
    Completed: !isStart // TRUE only for the Kitting Completed event.
};
// 10. Display the event and container in the Node-RED editor.
node.status({ fill: "blue", shape: "dot", text: `${msg.kit_event} ${containerId}` });
// 11. Send the configured HTTP request to the Mendix HTTP Request node.
return msg;

/*
 * NODE PURPOSE: Builds the Mendix REST body when PLC reports Kitting Completed.
 * INPUT: msg.topic from the DB116 completion trigger.
 * COMMANDS:
 *   flow.get("cfg")        -> reads the Mendix endpoint configuration.
 *   flow.get("step4")      -> reads cached PLC batch/container identifiers.
 *   global.get("WO_QUEUE") -> finds the active work order and container.
 *   msg.url/method/headers -> configures an HTTP POST with JSON content.
 *   msg.payload            -> creates the completion status body.
 *   return msg             -> sends the body to the Completed HTTP Request node.
 *
 * EVENT CONTRACT:
 *   Started=false and Completed=true. The queue advances only after Mendix
