// 10. Display the event and container in the Node-RED editor.
node.status({ fill: "blue", shape: "dot", text: `${msg.kit_event} ${containerId}` });
// 11. Send the configured HTTP request to the Mendix HTTP Request node.
return msg;

/*
 * NODE PURPOSE: Checks Mendix HTTP results and advances the queue after completion.
 * INPUT: HTTP Request response plus kit_event, kit_badge and kit_container_index.
 * COMMANDS:
 *   includes(Number(msg.statusCode)) -> accepts HTTP 200/201/202/204 only.
 *   global.get("WO_QUEUE")           -> reads the queue after a successful response.
 *   queue.find(...)                  -> locates the badge that generated this event.
 *   Number(...)                      -> compares the returned container index.
 *   b.next_container_index++         -> advances to the next container once.
 *   b.queue_status                   -> sets pending or completed.
 *   global.set(...)                  -> saves queue changes.
 *   flow.get("waiting")              -> checks whether PLC release was waiting.
 *   return [msg,kick]                -> output 1 reports result; output 2 wakes FIFO writer.
 *
 * IMPORTANT:
 *   A failed HTTP response does not advance the queue. This version reports failure;
 *   it does not automatically retry the Mendix request.
 */

// FUNCTION: Check Mendix Response
// PURPOSE: Validate the HTTP response received from the Mendix REST API.
// INPUT: kit_event, kit_badge, kit_container_index, statusCode and payload.
// OUTPUT: Debug/status message showing success or failure.
// ACCEPTED HTTP: 200, 201, 202 and 204.
// EFFECT: Only successful Completed responses advance the container index.
// NOTE: HTTP success does not confirm PLC ACK; PLC ACK is handled separately.
// 1. Check whether Mendix returned an accepted successful HTTP status.
const ok = [200, 201, 202, 204].includes(Number(msg.statusCode));
// OUTPUT 1: result for Debug | OUTPUT 2: "kick" to Fetch Next Badge when the PLC released while this container was active
let kick = null;

// 2. Handle unsuccessful HTTP responses without changing the queue.
if (!ok) {
    node.status({ fill: "red", shape: "ring", text: `Mendix HTTP ${msg.statusCode}` });
    node.warn(`Mendix kitting ${msg.kit_event} FAILED: HTTP ${msg.statusCode} ${String(msg.payload).slice(0, 120)}`);
    msg.payload = `FAILED (${msg.statusCode}) kitting ${msg.kit_event}`;
    return [msg, null]; // Stop processing and report failure.
}

// 3. Started confirms the REST call only; Completed advances the queue.
if (msg.kit_event === "completed") {
    let queue = global.get("WO_QUEUE") || []; // Load the shared badge queue.
    const b = queue.find(x => x.badge_id === msg.kit_badge); // Find the badge.
    if (!b) {
        node.warn(`Completed response received but badge ${msg.kit_badge} was not found.`);
    } else {
        // 4. Read the completed container index and expected queue index.
        const completedIndex = Number(msg.kit_container_index);
        const expectedIndex = Number.isInteger(b.next_container_index) ? b.next_container_index : 0;
        // 5. Ignore duplicate or stale responses for another container.
        if (completedIndex !== expectedIndex) {
            node.warn(`Ignoring stale completion for ${msg.kit_badge} container index ${completedIndex}; expected ${expectedIndex}.`);
        } else {
            // 6. Advance to the next container and clear the current index.
            b.next_container_index = expectedIndex + 1;
            b.current_container_index = null;
            // 7. Mark badge completed if all containers are processed.
            if (b.next_container_index >= b.containers.length) {
                b.queue_status = "completed";
            } else {
                b.queue_status = "pending"; // Wait for next PLC release.
            }
            global.set("WO_QUEUE", queue); // Save the updated queue.
            // 8. Release the active badge/container lock for the next cycle.
            // (the lock is derived from the queue: status pending/completed + current_container_index null = released)
            // 8b. PLC already asked for the next container while this one was active: serve it now.
            if (flow.get("waiting")) kick = { payload: true, topic: "kick" };
            // 9. Read the completed-record retention limit from configuration.
            const cfg = flow.get("cfg") || {};
            const keep = Math.max(0, Number(cfg.keep_completed) || 50);
            const done = queue.filter(x => x.queue_status === "completed");
            // 10. Remove older completed records when the retention limit is exceeded.
            if (done.length > keep) {
                const dropIds = new Set(done.slice(0, done.length - keep).map(x => x.badge_id));
                queue = queue.filter(x => !dropIds.has(x.badge_id));
                global.set("WO_QUEUE", queue); // Save queue after cleanup.
            }
            // 11. Display the badge's final or next-container status.
            node.status({
                fill: "green", shape: "dot",
                text: b.queue_status === "completed"
                    ? `${b.badge_id} completed`
                    : `${b.badge_id}: next container pending`
            });
        }
    }
}

// 12. Display successful Mendix response status.
node.status({ fill: "green", shape: "dot", text: `${msg.kit_event} OK (${msg.statusCode})` });
// 13. Prepare the success message with event and batch information.
msg.payload = `OK (${msg.statusCode}) kitting ${msg.kit_event} batch ${msg.kit_batch}`;
// 14. Return the response message to the connected Debug/status node.
return [msg, kick];

// END: Mendix response validation and completion handling.

/*
 * NODE PURPOSE: Caches the latest Step-4 container ID read from PLC DB116.
 * INPUT: S7 message with topic DB116_step4_container_id and its string payload.
 * COMMANDS:
 *   flow.get("step4") -> reads the current cache object.
 *   String(...).trim() -> converts the PLC value to clean text.
 *   msg.topic check   -> stores the value in ids.container.
 *   flow.set("step4") -> saves the updated cache.
 *   return null       -> stops the message; this node only updates context.
 */

/* PURPOSE: Cache container and batch IDs read back from the PLC Step-4 area.
 * INPUT : S7 input messages. msg.topic must match one of the two exact names.
 * OUTPUT: None. Values are stored in flow context for the Mendix status payload.
 * NOTE: This cache is a fallback/source for status reporting; it is not the
 * primary work-queue record and should be checked against the active container.
 */

// Cache the latest PLC Step-4 IDs. S7 input topic should be the variable name.
const ids = flow.get("step4") || {};
const v = String(msg.payload == null ? "" : msg.payload).trim();

if (msg.topic === "DB116_step4_container_id") ids.container = v;
else if (msg.topic === "DB116_step4_batch_id") ids.batch = v;
else {
    node.warn(`Cache Step-4 IDs received unexpected topic: ${msg.topic}`);
    return null;
}

flow.set("step4", ids);
return null;

/*
 * NODE PURPOSE: Caches the latest Step-4 batch ID read from PLC DB116.
 * INPUT: S7 message with topic DB116_step4_batch_id and its string payload.
 * COMMANDS:
 *   flow.get("step4") -> reads the current cache object.
 *   String(...).trim() -> converts the PLC value to clean text.
 *   msg.topic check   -> stores the value in ids.batch.
 *   flow.set("step4") -> saves the updated cache.
 *   return null       -> stops the message; this node only updates context.
 */

/* PURPOSE: Cache container and batch IDs read back from the PLC Step-4 area.
 * INPUT : S7 input messages. msg.topic must match one of the two exact names.
 * OUTPUT: None. Values are stored in flow context for the Mendix status payload.
 * NOTE: This cache is a fallback/source for status reporting; it is not the
 * primary work-queue record and should be checked against the active container.
 */

// Cache the latest PLC Step-4 IDs. S7 input topic should be the variable name.
const ids = flow.get("step4") || {};
const v = String(msg.payload == null ? "" : msg.payload).trim();

if (msg.topic === "DB116_step4_container_id") ids.container = v;
else if (msg.topic === "DB116_step4_batch_id") ids.batch = v;
else {
    node.warn(`Cache Step-4 IDs received unexpected topic: ${msg.topic}`);
    return null;
}

flow.set("step4", ids);
return null;

/*
 * NODE PURPOSE: Initializes configuration and recovers queue state at Node-RED startup.
 * INPUT: One Inject message after deployment/startup.
 * COMMANDS:
 *   flow.set("cfg")           -> stores Mendix URL and queue/write settings.
 *   global.get("WO_QUEUE")    -> loads the shared queue from context storage.
 *   Array.isArray(...)        -> checks that the stored queue has the expected format.
 *   global.set("WO_QUEUE")    -> creates an empty queue if none exists.
 *   flow.get/set("waiting")   -> initializes the waiting-for-PLC flag.
 *   flow.get("pending_write")-> checks whether a write verification was in progress.
 *   for...of                 -> recovers records left in processing after restart.
 *   return null              -> startup initialization does not send a message onward.
 *
 * IMPORTANT:
 *   Persistence requires localfilesystem context storage in settings.js. Confirm the
 *   actual PLC state against GET /queue before resuming production after a restart.
 */

/* PURPOSE: Initialise shared configuration and recover the queue after a (re)start.
 * INPUT : None (inject on deploy/start).
 * OUTPUT: None. Config goes to flow context; the queue lives in global context WO_QUEUE.
 * NOTE  : The queue survives a Node-RED restart only if the localfilesystem
 *         context store is enabled in settings.js. The "active badge" is NOT stored
 *         separately: it is always derived from the queue (status processing/sent),
 *         so the lock and the queue can never disagree.
 */

const cfg = {
    mendix_kitting_url: "http://localhost:8080/rest/ktting/v1/Status",
    keep_completed: 50,
    write_confirm_timeout_ms: 3000,   // time allowed for the 19 DB116 values to appear in the PLC
    write_max_attempts: 3             // data write attempts before the badge is marked write_failed
};
flow.set("cfg", cfg);

let queue = global.get("WO_QUEUE");
if (!Array.isArray(queue)) {
    queue = [];
    global.set("WO_QUEUE", queue);
}
if (flow.get("waiting") === undefined) flow.set("waiting", false);

// Restart recovery: only when no write verification is currently running.
//  processing = data written but no ACK seen -> back to pending, it is written (and verified) again
//  sent       = PLC acknowledged the data   -> stays locked until the Kitting Complete trigger
// LIMIT: Edge cannot read the PLC's real buffer state with the current tag list.
//        After a restart check the PLC against GET /queue before releasing production.
if (!flow.get("pending_write")) {
    for (const b of queue) {
        if (b.queue_status === "processing") {
            b.queue_status = "pending";
            b.current_container_index = null;
            node.warn(`Recovery: badge ${b.badge_id} was processing without ACK; set back to pending`);
        }
    }
    global.set("WO_QUEUE", queue);
}
flow.set("pending_write", flow.get("pending_write") || null);

node.status({fill:"green", shape:"dot", text:"config loaded"});
return null;

// FUNCTION: Validate & Enqueue
// Supports single work order and work_orders[] array.
// Output 1: Success | Output 2: Error | Output 3: PLC kick

// 1. Read incoming payload.
const p = msg.payload || {};
const workOrders = Array.isArray(p.work_orders) ? p.work_orders : [p];

// 2. Validate all work orders.
const valid = workOrders.length > 0 && workOrders.every(w =>
    w &&
    typeof w.badge_id === "string" && w.badge_id.trim() &&
    typeof w.batch_id === "string" && w.batch_id.trim() &&
    Array.isArray(w.containers) && w.containers.length > 0 &&
    w.containers.every(c =>
        c && typeof c.container_name === "string" &&
        c.container_name.trim() && Array.isArray(c.tasks)
    )
);

// 3. Reject invalid payload.
if (!valid) {
    msg.statusCode = 422;
    msg.headers = { "Content-Type": "application/json" };
    msg.payload = { error: "Each work order requires badge_id, batch_id and containers[]. Each container requires container_name and tasks[]." };
    node.status({ fill: "red", shape: "ring", text: "422 invalid payload" });
    return [null, msg, null];
}

// 4. Check duplicate badge IDs in the request.
const ids = workOrders.map(w => w.badge_id.trim());
if (new Set(ids).size !== ids.length) {
    msg.statusCode = 422;
    msg.headers = { "Content-Type": "application/json" };
    msg.payload = { error: "Duplicate badge_id found in request" };
    return [null, msg, null];
}

// 5. Load existing FIFO queue.
const queue = global.get("WO_QUEUE") || [];

// 6. Prevent updates to active badges.
for (const id of ids) {
    const old = queue.find(b => b.badge_id === id);
    if (old && ["processing", "sent"].includes(old.queue_status)) {
        msg.statusCode = 409;
        msg.headers = { "Content-Type": "application/json" };
        msg.payload = {
            error: "Badge is already active",
            badge_id: id,
            queue_status: old.queue_status
        };
        return [null, msg, null];
    }
}

// 7. Insert or update each work order.
const accepted = [];
for (const w of workOrders) {
    const badgeId = w.badge_id.trim();
    const batchId = w.batch_id.trim();
    const idx = queue.findIndex(b => b.badge_id === badgeId);
    const record = {
        badge_id: badgeId,
        batch_id: batchId,
        containers: w.containers,
        next_container_index: 0,
        queue_status: "pending",
        created_at: idx >= 0 ? queue[idx].created_at : new Date().toISOString()
    };
    if (idx >= 0) queue[idx] = record;
    else queue.push(record);
    accepted.push({
        badge_id: badgeId,
        batch_id: batchId,
        queue_status: "pending",
        container_count: record.containers.length
    });
}

// 8. Save FIFO queue.
global.set("WO_QUEUE", queue);

// 9. Count pending work orders.
const pending = queue.filter(b => b.queue_status === "pending").length;

// 10. Prepare success response.
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    status: "success",
    message: "Work orders added to FIFO queue",
    accepted_count: accepted.length,
    work_orders: accepted,
    pending_count: pending
};

// 11. Update Node-RED status.
node.status({
    fill: "green",
    shape: "dot",
    text: `stored ${accepted.length} | pending ${pending}`
});

// 12. Wake PLC writer if waiting.
const kick = flow.get("waiting")
    ? { payload: true, topic: "kick" }
    : null;

// 13. Return three outputs.
return [msg, null, kick];

/* PURPOSE: Serve the read-only queue APIs.
 * INPUT : HTTP request. /badges returns complete records; /queue returns a
 * compact status summary without the full container/task payload.
 * OUTPUT: HTTP 200 with JSON. This function does not modify queue records.
 */

const queue = global.get("WO_QUEUE") || [];
const full = (msg.req && msg.req.url || "").startsWith("/badges");

msg.statusCode = 200;
msg.headers = {"Content-Type":"application/json"};
msg.payload = full ? queue : queue.map(b => ({
    badge_id: b.badge_id,
    batch_id: b.batch_id,
    queue_status: b.queue_status,
    next_container_index: b.next_container_index || 0,
    container_count: Array.isArray(b.containers) ? b.containers.length : 0,
    created_at: b.created_at
}));
return msg;

const now = new Date();
let input;
try { input = JSON.stringify(msg.payload); } catch (e) { input = '[unserializable]'; }
if (input && input.length > 2000) input = input.slice(0, 2000) + '…[truncated]';

const entry = {
    ts: now.toISOString(),
    level: 'error',
    node: msg.error?.source?.name || msg.error?.source?.id,
    nodeType: msg.error?.source?.type,
    error: msg.error?.message,
    id: msg._msgid,
    input: input
};

return {
    filename: `/data/logs/app-${now.toISOString().slice(0,10)}.log`,
    payload: JSON.stringify(entry)
};
